import json,html, pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
sources=json.loads((ROOT/'data/sources.json').read_text())
wiki=json.loads((ROOT/'data/wiki.json').read_text())
slides=json.loads((ROOT/'data/slides.json').read_text())
style='''
:root{--bg:#0b1423;--panel:#142238;--panel2:#192a42;--ink:#edf4fd;--muted:#a9bbd1;--accent:#70dbca;--gold:#f3c781;--line:#31445c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 system-ui,-apple-system,"Noto Sans TC",sans-serif}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}.wrap{max-width:1190px;padding:28px;margin:auto}.header{display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:19px}.brand{font-weight:850;letter-spacing:.09em;font-size:15px}.links{display:flex;gap:18px;flex-wrap:wrap}.links a{font-size:14px}.hero{padding:60px 0 35px}.tag{color:var(--accent);font-weight:750;font-size:12px;letter-spacing:.16em;text-transform:uppercase}.hero h1{line-height:1.13;letter-spacing:-.045em;font-size:clamp(42px,6vw,72px);max-width:920px;margin:12px 0}.hero p{color:var(--muted);font-size:18px;max-width:780px}.btn{display:inline-block;background:var(--accent);color:#0b1423;border:0;border-radius:11px;padding:11px 19px;font:inherit;font-weight:800;cursor:pointer}.btn.secondary{background:transparent;border:1px solid var(--line);color:var(--ink)}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:23px 0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:var(--panel);padding:18px;border:1px solid var(--line);border-radius:16px}.stat b{font-size:28px;color:var(--accent)}.stat p{margin:0;color:var(--muted);font-size:13px}.sectiontitle{margin-top:48px}.filters{display:flex;gap:7px;flex-wrap:wrap}.filters button{cursor:pointer;background:var(--panel);color:var(--ink);border:1px solid var(--line);padding:8px 12px;border-radius:22px}.filters button.active{background:var(--accent);color:#061421}.search{width:100%;background:var(--panel);border:1px solid var(--line);padding:13px 16px;color:var(--ink);border-radius:11px;font:inherit}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(285px,1fr));gap:15px;margin-top:20px}.card{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:23px}.card h3{margin:7px 0}.card p{color:var(--muted)}.tiny{font-size:12px;color:var(--accent)}.pill{display:inline-block;border:1px solid var(--line);border-radius:25px;padding:3px 9px;margin:3px;font-size:12px;color:var(--muted)}details{margin-top:12px;border-top:1px solid var(--line);padding-top:10px}summary{cursor:pointer;color:var(--accent)}.sourcebox{border-left:3px solid var(--gold);padding-left:12px;margin:14px 0;color:var(--muted)}.flowbox{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.flowstep{padding:10px 16px;background:var(--panel);border:1px solid var(--line);border-radius:10px}.flowarrow{align-self:center;color:var(--accent)}.note{background:#1a293c;padding:18px;border-radius:12px;border:1px solid var(--line)}footer{margin:60px 0 18px;padding-top:16px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}@media(max-width:600px){.stats{grid-template-columns:1fr}.header{align-items:flex-start;flex-direction:column}}
'''
common_header='<header class="header"><div class="brand">◈ ANALOG / LLM WIKI</div><nav class="links"><a href="index.html">Wiki 知識庫</a><a href="slides.html">教學簡報</a><a href="workflow.html">Workflow 與紀錄</a></nav></header>'
head=lambda title:f'<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><style>{style}</style></head><body><div class="wrap">{common_header}'
footer='<footer>Analog LLM Wiki · 教學用途 · 每條知識均提供公開來源連結 · 本專案內容為人工整理摘要，不代表原廠逐字原文</footer></div></body></html>'
# interactive wiki
idx=head('Analog LLM Wiki｜OTA 與 Sizing')+'''<section class="hero"><div class="tag">Knowledge-grounded learning</div><h1>從 OTA 到<br>Transistor Sizing</h1><p>一個可以搜尋、核對來源、連接教學簡報的類比電路入門知識庫。每個知識節點均有可追溯的公開來源。</p><div class="toolbar"><a class="btn" href="slides.html">開始教學簡報 ↗</a><a class="btn secondary" href="workflow.html">查看 Workflow</a></div></section><section class="stats"><div class="stat"><b>7</b><p>公開來源整理（ingested summaries）</p></div><div class="stat"><b>7</b><p>Wiki 知識節點</p></div><div class="stat"><b>13</b><p>有引用對應的教學投影片</p></div></section><h2 class="sectiontitle">可查詢的 Wiki 節點</h2><input id="q" class="search" placeholder="搜尋 OTA、gm、ro、GBW、Sizing、SPICE…" aria-label="搜尋知識"><div id="filters" class="filters" style="margin-top:15px"></div><div id="cards" class="cards"></div><h2 class="sectiontitle">參考資料 / Ingestion manifest</h2><p style="color:var(--muted)">以下為 7 篇來源的人工擷取摘要，保留標題、URL、重點與來源 ID；並非全文爬取或向量資料庫。</p><div id="sources" class="cards"></div>'''
idx+='''<script>const WIKI=__WIKI__,SOURCES=__SOURCES__;const $=s=>document.querySelector(s);let cat='全部';function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function render(){const q=$('#q').value.toLowerCase();const items=WIKI.filter(w=>(cat==='全部'||w.category===cat)&&JSON.stringify(w).toLowerCase().includes(q));$('#cards').innerHTML=items.length?items.map(w=>`<article class="card" id="${w.id}"><span class="tiny">${w.id} · ${escapeHTML(w.category)}</span><h3>${escapeHTML(w.title)}</h3><p>${escapeHTML(w.definition)}</p><details><summary>展開知識內容與注意事項</summary><p>${escapeHTML(w.body)}</p><div class="sourcebox">注意：${escapeHTML(w.pitfall)}</div></details><div class="tiny">知識來源</div>${w.sources.map(id=>{let s=SOURCES.find(x=>x.id===id);return `<a class="pill" target="_blank" rel="noopener" href="${s.url}">${id} · ${escapeHTML(s.publisher)}</a>`}).join('')}</article>`).join(''):'<p>沒有符合條件的節點</p>';}$('#filters').innerHTML=['全部',...new Set(WIKI.map(x=>x.category))].map(c=>`<button data-cat="${c}">${c}</button>`).join('');$('#filters').onclick=e=>{if(e.target.dataset.cat){cat=e.target.dataset.cat;document.querySelectorAll('#filters button').forEach(b=>b.classList.toggle('active',b.dataset.cat===cat));render()}};$('#filters button').classList.add('active');$('#q').oninput=render;render();$('#sources').innerHTML=SOURCES.map(s=>`<article class="card"><span class="tiny">${s.id} · ${escapeHTML(s.topic)}</span><h3>${escapeHTML(s.title)}</h3><p>${escapeHTML(s.summary)}</p><ul>${s.facts.map(f=>`<li>${escapeHTML(f)}</li>`).join('')}</ul><a href="${s.url}" rel="noopener" target="_blank">查看原始來源 ↗</a><p class="tiny">${s.status}</p></article>`).join('');</script>'''.replace('__WIKI__',json.dumps(wiki,ensure_ascii=False)).replace('__SOURCES__',json.dumps(sources,ensure_ascii=False))
(ROOT/'index.html').write_text(idx+footer)
# slides
slides_css='''body.deck{overflow:hidden}.deck .wrap{max-width:none;padding:0;height:100dvh;display:flex;flex-direction:column}.deck .header{padding:12px 3vw}.deckmain{flex:1;display:flex;align-items:stretch;min-height:0}.slide{width:100%;display:flex;flex-direction:column;justify-content:center;padding:clamp(25px,5vw,85px) clamp(28px,8vw,150px);background:radial-gradient(ellipse at 84% 19%,#24415b 0%,transparent 42%);overflow:auto}.slide h1{font-size:clamp(38px,5.4vw,78px);line-height:1.14;letter-spacing:-.04em;margin:12px 0 24px;max-width:1040px}.slide .summary{font-size:clamp(19px,2.2vw,30px);color:var(--accent);max-width:1100px}.slide ul{font-size:clamp(17px,1.7vw,25px);line-height:1.8;padding-left:1.4em;max-width:1150px}.slide li{padding-left:.1em;margin:7px 0}.formula{display:inline-block;background:#132a3a;border:1px solid #30616a;color:#f2e2b7;padding:15px 25px;border-radius:14px;font-size:clamp(22px,2.7vw,40px);margin:12px 0}.controls{display:flex;align-items:center;gap:13px;padding:12px 3vw;border-top:1px solid var(--line);background:#0b1423}.controls button{background:#1a2a40;color:white;border:1px solid var(--line);padding:7px 15px;border-radius:10px;cursor:pointer;font:inherit}.controls button:disabled{opacity:.4}.controls .right{margin-left:auto}.progress{height:3px;background:#263950}.progress>div{background:var(--accent);height:100%;transition:width .2s}.stage{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:18px 0}.stage span{padding:15px 20px;border:1px solid var(--line);background:var(--panel);border-radius:12px}.stage i{color:var(--accent);font-style:normal}.quizopts{display:grid;gap:12px;max-width:800px}.quizopts button{color:white;text-align:left;font:inherit;background:var(--panel);border:1px solid var(--line);padding:16px;border-radius:12px;cursor:pointer}.quizopts button.good{border-color:#72d5a9}.quizopts button.bad{border-color:#f49a90}.quizfeedback{min-height:28px;color:var(--gold)}#refs{position:absolute;right:3vw;bottom:70px;background:#152437;border:1px solid var(--line);padding:18px;border-radius:12px;max-width:360px;box-shadow:0 10px 25px #0008}#refs[hidden]{display:none}.deck footer{display:none}@media(max-width:650px){.deck .header{padding:8px 12px}.deck .links{gap:8px}.slide{justify-content:flex-start;padding:30px 23px}.controls{gap:5px}.controls button{padding:5px 9px}}'''
slide_html=head('HTML 教學簡報｜OTA 與 Sizing').replace('<body>','<body class="deck">').replace('</style>',''+slides_css+'</style>')
slide_html+='''<main class="deckmain"><article id="slide" class="slide" aria-live="polite"></article></main><div class="progress"><div id="bar"></div></div><div class="controls"><button id="prev">← 上一頁</button><button id="next">下一頁 →</button><button id="refbtn">Wiki 依據</button><span class="right" id="count"></span><button id="fullscreen">全螢幕</button></div><aside id="refs" hidden></aside>'''
slide_html+='''<script>const SLIDES=__SLIDES__,WIKI=__WIKI__,SOURCES=__SOURCES__;let index=0;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function draw(){const s=SLIDES[index];$('#refs').hidden=true;let diagram=s.diagram==='stages'?'<div class="stage"><span>Vin+ / Vin−</span><i>→</i><span>差動輸入級</span><i>→</i><span>第二增益級</span><i>→</i><span>Vout</span></div>':s.diagram==='loop'?'<div class="stage"><span>規格</span><i>→</i><span>選 W/L</span><i>→</i><span>SPICE</span><i>→</i><span>檢查</span><i>↺</i><span>修正參數</span></div>':'';let quiz=s.quiz?`<div class="quizopts">${s.quiz.options.map((o,i)=>`<button data-opt="${i}">${esc(o)}</button>`).join('')}</div><div class="quizfeedback" id="quizfb"></div>`:'';$('#slide').innerHTML=`<div class="tag">${esc(s.eyebrow)}</div><h1>${esc(s.title)}</h1><p class="summary">${esc(s.summary)}</p>${s.formula?`<div><div class="formula">${esc(s.formula)}</div></div>`:''}${diagram}<ul>${(s.points||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${quiz}`;if(s.quiz){$('#slide').addEventListener('click',quizClick,{once:false});}$('#bar').style.width=((index+1)/SLIDES.length*100)+'%';$('#count').textContent=`${String(index+1).padStart(2,'0')} / ${SLIDES.length}`;$('#prev').disabled=index===0;$('#next').disabled=index===SLIDES.length-1;location.hash='slide-'+(index+1);}function quizClick(e){let b=e.target.closest('[data-opt]');if(!b)return;const q=SLIDES[index].quiz;if(!q)return;const correct=Number(b.dataset.opt)===q.correct;document.querySelectorAll('[data-opt]').forEach(n=>{n.classList.toggle('good',Number(n.dataset.opt)===q.correct);n.classList.toggle('bad',n===b&&!correct)});$('#quizfb').textContent=(correct?'答對了。':'還可以再想想。')+q.explanation;}function move(x){index=Math.max(0,Math.min(SLIDES.length-1,index+x));draw()}$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);$('#refbtn').onclick=()=>{let a=$('#refs');a.hidden=!a.hidden;if(!a.hidden){a.innerHTML='<strong>本頁 Wiki 依據</strong><br>'+SLIDES[index].wiki.map(id=>{let w=WIKI.find(x=>x.id===id);return `<p><a href="index.html#${id}" target="_blank">${id} · ${esc(w.title)}</a><br><span style="color:#a9bbd1;font-size:12px">來源 ${w.sources.join(', ')}</span></p>`}).join('')}};$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.()};document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();move(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();move(-1)}});const h=parseInt((location.hash.match(/slide-(\\d+)/)||[])[1]);if(h&&h>=1&&h<=SLIDES.length)index=h-1;draw();</script>'''.replace('__SLIDES__',json.dumps(slides,ensure_ascii=False)).replace('__WIKI__',json.dumps(wiki,ensure_ascii=False)).replace('__SOURCES__',json.dumps(sources,ensure_ascii=False))
(ROOT/'slides.html').write_text(slide_html+footer)
flow=head('Workflow 與檢查紀錄')+'''<section class="hero"><div class="tag">Grounded generation pipeline</div><h1>Loop / Graph 設計</h1><p>讓資料擷取、知識整理與簡報產出均有驗證條件；若驗證不通過，就退回相應節點修正。</p></section><h2>實際實作的節點</h2><div class="flowbox"><span class="flowstep">選題與來源蒐集</span><span class="flowarrow">→</span><span class="flowstep">Ingest 來源摘要</span><span class="flowarrow">→</span><span class="flowstep">建立 Wiki 節點</span><span class="flowarrow">→</span><span class="flowstep">檢索相關 Wiki</span><span class="flowarrow">→</span><span class="flowstep">規劃教學順序</span><span class="flowarrow">→</span><span class="flowstep">生成 HTML</span><span class="flowarrow">→</span><span class="flowstep">檢查與重試</span></div><div class="cards"><article class="card"><h3>Loop A｜來源檢查</h3><p>每一條 source 必須有 ID、標題、URL、摘要與事實。若資訊不完整，退回來源整理；若無法追溯，不能進入 Wiki。</p></article><article class="card"><h3>Loop B｜Wiki 對應</h3><p>每個 Wiki 節點都要至少有一個合法 source ID；每頁教學簡報都要有合法 Wiki ID，否則停止建置並修正對應。</p></article><article class="card"><h3>Loop C｜教學檢查</h3><p>確認入門順序、術語、公式的適用條件及互動。若有不明確或太艱深的敘述，回到 Wiki 整理後重建投影片。</p></article></div><h2 class="sectiontitle">為什麼把檢查往前移？</h2><p>單純在 HTML 產生後才檢查，很難知道錯誤來自原始資料、Wiki 或投影片。現在優先在 <strong>Wiki 建立後、簡報生成前</strong> 做來源引用與定義檢查，避免錯誤被擴散到多張投影片。</p><h2 class="sectiontitle">執行與測試</h2><div class="note"><p>本頁的實際檢查結果由 <code>python3 scripts/validate.py</code> 產生，詳細輸出可參考 <a href="docs/validation-report.txt">validation-report.txt</a>。此為可重複執行的規則式檢查，並非宣稱系統已使用 LLM 自動判斷所有技術敘述。</p></div><h2 class="sectiontitle">Reflection</h2><p><strong>最容易出錯的節點：</strong>Wiki → Slides 的內容映射，尤其是簡報頁可能漏掉對應 Wiki ID，或簡化公式時省略必要適用條件。</p><p><strong>檢查前移：</strong>在生成 HTML 前先執行 source→Wiki→slide 引用完整性檢查，並在 Wiki 內新增「易混淆處」欄位。</p><p><strong>修改方式：</strong>原本單向來源→Wiki→簡報改為含失敗回邊的流程；任何引用錯誤都阻止 build，退回上一步修正後重建。</p><p><a href="docs/workflow.md">開啟完整流程 Markdown</a></p>'''
(ROOT/'workflow.html').write_text(flow+footer)
print('Generated index.html, slides.html, workflow.html')
